/* ===================== BÀI 20 · Build, listing và đối chiếu Assembly ===================== */
/* Bài 20 · Build, listing và đối chiếu Assembly (AMTS-EMB-001-M05-L04, MC51-020) — sinh bởi tools/author/mcu8051/l20.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P20=[{"label":"Ví dụ: Một dòng C, nhiều lệnh trong listing","code":"; Ví dụ 1: x ở 30H, y ở 31H. Mã SDCC 4.2.0 sinh cho\n; 01.c51, chép từ listing (.rst): mỗi nhóm lệnh đứng\n; dưới đúng dòng C của nó.\n        ORG     0000H\n        MOV     30H,#07H                ; x = 7;\n        MOV     A,30H                   ; y = x * 3 + 1;\n        MOV     B,#03H\n        MUL     AB                      ;   4 chu kỳ máy\n        INC     A\n        MOV     31H,A\n        MOV     A,31H                   ; P1 = ~y;\n        CPL     A\n        MOV     P1,A\n        SJMP    $                       ; while (1);\n        END\n","note":"Một dòng C y = x * 3 + 1 thành 5 lệnh, trong đó MUL AB tốn 4 chu kỳ. Đoán trước: sau MUL AB, A và B bằng bao nhiêu? (A = 15H, B = 00H: 7 × 3 = 21.) Cuối cùng y = 16H, P1 = ~16H = E9H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Cùng phép cộng, 8 bit tràn, 16 bit đủ","code":"; Ví dụ 2: t (8 bit) ở 30H, u (16 bit) ở 32H-33H.\n; Mã SDCC 4.2.0 sinh cho 02.c51.\n        ORG     0000H\n        MOV     30H,#0C8H               ; t = 200;\n        MOV     R7,30H                  ; t = t + 100;\n        MOV     A,#64H\n        ADD     A,R7                    ;   12CH: CY = 1 bị bỏ qua\n        MOV     30H,A                   ;   t = 2CH = 44\n        MOV     32H,#0C8H               ; u = 200;\n        MOV     33H,#00H\n        MOV     A,#64H                  ; u = u + 100;\n        ADD     A,32H                   ;   byte thấp, CY = 1\n        MOV     32H,A\n        CLR     A\n        ADDC    A,33H                   ;   byte cao nhận CY\n        MOV     33H,A                   ;   u = 012CH = 300\n        SJMP    $                       ; while (1);\n        END\n","note":"Cùng phép +100 trên hai kiểu. Đoán trước: sau ADD A,R7, A và CY? (A = 2CH, CY = 1: 200 + 100 = 12CH, bit 9 rơi vào CY và bị bỏ.) Biến 16 bit u giữ được: ADDC đưa CY vào byte cao, u = 012CH.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chi phí của một hàm ngắn","code":"; Ví dụ 3: hàm show(v) { P1 = ~v; } gọi hai lần.\n; Mã SDCC 4.2.0 sinh cho 03.c51; tham số qua DPL.\n        ORG     0000H\n        MOV     DPL,#81H                ; show(0x81);\n        LCALL   SHOW\n        MOV     DPL,#18H                ; show(0x18);\n        LCALL   SHOW\n        SJMP    $                       ; while (1);\nSHOW:   MOV     A,DPL                   ; P1 = ~v;\n        CPL     A\n        MOV     P1,A\n        RET\n        END\n","note":"Mỗi lời gọi show(v): MOV DPL (2) + LCALL (2) + thân hàm (3) + RET (2) = 9 chu kỳ; hai lời gọi 18 chu kỳ. Viết thẳng P1 = ~0x81 chỉ là một lệnh MOV P1,#7EH (2 chu kỳ). Xem ngăn xếp 08H–09H khi LCALL.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chia cho 8 bằng dịch bit","code":"; Ví dụ 4: x ở 30H, q ở 31H, r ở 32H.\n; Mã SDCC 4.2.0 sinh cho 04.c51: x >> 3 thành\n; SWAP + RL (quay trái 5 = quay phải 3) rồi che.\n        ORG     0000H\n        MOV     30H,#0B5H               ; x = 0xB5;\n        MOV     A,30H                   ; q = x >> 3;\n        SWAP    A                       ;   B5H -> 5BH\n        RL      A                       ;   5BH -> B6H\n        ANL     A,#1FH                  ;   giữ 5 bit thấp: 16H\n        MOV     31H,A\n        MOV     A,30H                   ; r = x & 7;\n        ANL     A,#07H\n        MOV     32H,A\n        SJMP    $                       ; while (1);\n        END\n","note":"x >> 3 với x không dấu: quay trái 5 lần = quay phải 3 lần, nên SWAP (4) + RL (1) rồi ANL #1FH bỏ 3 bit quay vòng. Đoán trước: A sau RL? (B6H.) q = 16H = 22, r = 05H. Viết x / 8 thì SDCC gọi thư viện: 392 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: So int với unsigned int","code":"; Ví dụ 5 (bẫy): int a = -1 (30H-31H) so với\n; unsigned int b = 1 (32H-33H). C đổi a sang unsigned:\n; FFFFH < 0001H sai. SDCC so 16 bit KHÔNG dấu, không\n; cảnh báo. Mã SDCC 4.2.0 sinh cho 05.c51.\n        ORG     0000H\n        MOV     30H,#0FFH               ; a = -1;  (FFFFH)\n        MOV     31H,#0FFH\n        MOV     32H,#01H                ; b = 1;\n        MOV     33H,#00H\n        MOV     R6,30H                  ; if (a < b)\n        MOV     R7,31H\n        CLR     C                       ;   a - b, byte thấp\n        MOV     A,R6\n        SUBB    A,32H\n        MOV     A,R7                    ;   byte cao\n        SUBB    A,33H\n        JNC     KHAC                    ;   không mượn: a >= b\n        MOV     P1,#00H                 ;     P1 = 0x00;\n        SJMP    XONG\nKHAC:   MOV     P1,#0F0H                ; else P1 = 0xF0;\nXONG:   SJMP    $                       ; while (1);\n        END\n","note":"Bẫy: a = -1 bị đổi sang unsigned (FFFFH) để so với b. Đoán trước: sau SUBB byte cao, CY = ? (0: FFH − 00H không mượn), nên JNC nhảy sang else: P1 = F0H. SDCC không cảnh báo. Sửa: if (a < (int)b).","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Hằng 60 * 1000 tràn int","code":"; Ví dụ 6 (bẫy): ms = 60 * 1000; với ms unsigned long\n; ở 30H-33H. 60 * 1000 tính bằng int: 60000 thành\n; -5536 (EA60H) rồi mới đổi sang long: FFFFEA60H.\n; SDCC tính sẵn hằng, báo warning 165 và 158.\n        ORG     0000H\n        MOV     30H,#60H                ; byte thấp nhất\n        MOV     31H,#0EAH\n        MOV     32H,#0FFH               ; mở rộng dấu: FF, FF\n        MOV     33H,#0FFH               ;   (đúng ra phải là 00, 00)\n        SJMP    $                       ; while (1);\n        END\n","note":"Bẫy: 60 * 1000 tính bằng int (16 bit có dấu): 60000 = EA60H hiểu là −5536, mở rộng dấu sang long thành FFFFEA60H. SDCC tính sẵn hằng nên chỉ còn 4 lệnh MOV; xem ô 32H, 33H = FFH. Sửa: 60UL * 1000.","dev":{"led":true},"fosc":12000000}];
const sim20=makeSim51(document.getElementById("m51-l20"),{id:"s20",presets:P20,ram:256});
makeEx51(document.getElementById("ex-l20"),"l20",[{"t":"Cộng bão hòa","d":"<p>Viết đoạn hợp ngữ làm đúng việc của đoạn C51 sau (<code>unsigned char<\/code>: <code>a<\/code> ở <code>30H<\/code>, <code>b<\/code> ở <code>31H<\/code>, <code>y<\/code> ở <code>32H<\/code>):<\/p><pre class=\"mc-asm\">unsigned int s;\ns = a + b;\nif (s &gt; 255) y = 255;\nelse         y = s;<\/pre><p>Ô <code>30H<\/code>, <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>a = 0AH<\/code>, <code>b = 14H<\/code> → <code>y = 1EH<\/code>; <code>a = C8H<\/code>, <code>b = 64H<\/code> → <code>y = FFH<\/code>.<\/p>","start":"; Bài tập 1: a ở 30H, b ở 31H, y ở 32H.\n; Code mẫu cộng 8 bit: sai khi a + b > 255.\n        ORG     0000H\n        MOV     A,30H                   ; s = a + b;\n        ADD     A,31H\n        MOV     32H,A                   ; y = s;  (thiếu kẹp ở 255)\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":10,"0x31":20,"0x32":238}},"expect":{"iram":{"0x30":10,"0x31":20,"0x32":30}}},{"setup":{"iram":{"0x30":200,"0x31":100,"0x32":238}},"expect":{"iram":{"0x30":200,"0x31":100,"0x32":255}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":100,"0x31":155,"0x32":238}},"expect":{"iram":{"0x30":100,"0x31":155,"0x32":255}}},{"setup":{"iram":{"0x30":255,"0x31":1,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":1,"0x32":255}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255}}}]},"hints":["Code mẫu cộng 8 bit: 200 + 100 cho 44 vì bit thứ 9 bị bỏ. Bit đó nằm trong cờ CY sau lệnh ADD.","s &gt; 255 đúng khi và chỉ khi phép cộng 8 bit có nhớ (CY = 1). Không cần tính s 16 bit.","Sau ADD có hai lối đi: không nhớ thì ghi tổng, có nhớ thì ghi giá trị bão hòa. Một lệnh nhảy theo CY là đủ."],"why":"Bộ thử 2 bắt lỗi tràn số kinh điển (cộng 8 bit cho 44 thay vì 255). Bộ thử 4 (100 + 155 = 255) kiểm không kẹp nhầm khi kết quả vừa đúng 255; bộ thử 5 (255 + 1) là lần tràn nhỏ nhất."},{"t":"Ngưỡng nhiệt độ có dấu","d":"<p>Viết đoạn hợp ngữ làm đúng việc của đoạn C51 sau. <code>signed char data t _at_ 0x30;<\/code> (−128…127, bù 2); <code>sbit LLOW = P1^0;<\/code>, <code>sbit LHIGH = P1^1;<\/code> (LED sáng khi chân = 0).<\/p><pre class=\"mc-asm\">if (t &lt; -10) LLOW = 0;\nif (t &gt; 40)  LHIGH = 0;<\/pre><p>Các chân khác của P1 giữ 1. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>t = ECH<\/code> (−20) → <code>P1 = FEH<\/code>; <code>t = 29H<\/code> (41) → <code>P1 = FDH<\/code>.<\/p>","start":"; Bài tập 2: t (signed char) ở 30H.\n; LED P1.0 sáng khi t < -10, LED P1.1 sáng khi t > 40.\n        ORG     0000H\n        MOV     A,30H                   ; if (t < -10)  -10 = F6H\n        CLR     C\n        SUBB    A,#0F6H                 ;   so KHÔNG dấu: sai với t >= 0\n        JNC     BOQUA\n        CLR     P1.0                    ;   LLOW = 0;\nBOQUA:                                  ; Viết tiếp: if (t > 40) LHIGH = 0;\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":236}},"expect":{"iram":{"0x30":236},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":25}},"expect":{"iram":{"0x30":25},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":246},"regs":{"PSW":128}},"expect":{"iram":{"0x30":246},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":245}},"expect":{"iram":{"0x30":245},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":40}},"expect":{"iram":{"0x30":40},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":41}},"expect":{"iram":{"0x30":41},"ports":{"P1":253}}},{"setup":{"iram":{"0x30":127}},"expect":{"iram":{"0x30":127},"ports":{"P1":253}}},{"setup":{"iram":{"0x30":128}},"expect":{"iram":{"0x30":128},"ports":{"P1":254}}}]},"hints":["CJNE, SUBB + CY so số KHÔNG dấu: với t = 25 (19H) và −10 (F6H), 19H &lt; F6H nên code mẫu bật nhầm LED lạnh.","Mẹo so có dấu trên 8051: đảo bit 7 của cả hai vế (XRL A,#80H) rồi so không dấu. −128…127 thành 00H…FFH, giữ đúng thứ tự.","Đổi cả hai ngưỡng sang thang mới (đảo bit 7) rồi so như số không dấu; t &gt; 40 tương đương t ≥ 41."],"why":"Lỗi sai dấu (signedness): t là signed char nên phép so phải có dấu, nhưng lệnh so của 8051 là không dấu. Bộ thử 2 (25 độ) bắt lỗi so không dấu; bộ thử 3–6 kiểm biên −10, −11, 40, 41; bộ thử 7–8 kiểm −128 và 127."},{"t":"Tách chữ số không cần thư viện","d":"<p>Đoạn C51 dưới đây tách <code>x<\/code> (ô <code>30H<\/code>, 0…255) thành chữ số hàng trăm, chục, đơn vị (ô <code>31H<\/code>, <code>32H<\/code>, <code>33H<\/code>):<\/p><pre class=\"mc-asm\">tr = x / 100;\nch = (x / 10) % 10;\ndv = x % 10;<\/pre><p>SDCC 4.2.0 dịch mỗi phép <code>/<\/code>, <code>%<\/code> ở đây thành một lời gọi hàm chia 16 bit có dấu của thư viện (x được nâng lên int): hàng trăm chu kỳ máy. Code mẫu là bản hợp ngữ trừ lặp: đúng nhưng chậm. Hãy viết lại để với mọi <code>x<\/code>: (1) ba ô kết quả đúng; (2) <code>30H<\/code> giữ nguyên; (3) chạy không quá <b>24 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>); (4) mã không quá <b>24 byte<\/b>.<\/p>","start":"; Bài tập 3: x ở 30H -> tr (31H), ch (32H), dv (33H).\n; Code mẫu trừ lặp: đúng nhưng chậm. Sửa để chạy\n; <= 24 chu kỳ máy và <= 24 byte.\n        ORG     0000H\n        MOV     A,30H\n        MOV     R7,#00H                 ; đếm số lần trừ được 100\nTRAM:   CLR     C\n        SUBB    A,#100\n        JC      HETTR\n        INC     R7\n        SJMP    TRAM\nHETTR:  ADD     A,#100                  ; trả lại lần trừ thừa\n        MOV     31H,R7                  ; tr\n        MOV     R7,#00H                 ; đếm số lần trừ được 10\nCHUC:   CLR     C\n        SUBB    A,#10\n        JC      HETCH\n        INC     R7\n        SJMP    CHUC\nHETCH:  ADD     A,#10\n        MOV     32H,R7                  ; ch\n        MOV     33H,A                   ; dv\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":47,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":47,"0x31":0,"0x32":4,"0x33":7}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":255,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":255,"0x31":2,"0x32":5,"0x33":5}}},{"setup":{"iram":{"0x30":100,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":100,"0x31":1,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":99,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":99,"0x31":0,"0x32":9,"0x33":9}}},{"setup":{"iram":{"0x30":209,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":209,"0x31":2,"0x32":0,"0x33":9}}}],"maxCyc":24,"maxBytes":24},"hints":["8051 có sẵn lệnh chia 8 bit: DIV AB cho A = A / B và B = A % B (số dư) trong 4 chu kỳ máy.","Chia x cho 100: thương là hàng trăm, số dư (0…99) còn lại trong B. Chuyển số dư sang A rồi chia tiếp cho 10.","Sau lần chia thứ hai, A và B đã là hai chữ số còn lại; không cần thêm phép tính nào."],"why":"Phép / và % trên unsigned char bị nâng lên int có dấu nên SDCC gọi hàm thư viện __divsint, __modsint (xem chẩn đoán 08-chia-10: 525 chu kỳ cho một lần / và một lần %). DIV AB chia 8 bit không dấu trong 4 chu kỳ: lời giải tham chiếu 20 chu kỳ, 21 byte."}]);

makeQuiz("quiz20","score20",[{"q": "Trong listing .rst của SDCC, dòng “00006A A4 [48] mul ab” cho biết MUL AB tốn bao nhiêu chu kỳ máy?", "o": ["48", "1", "12", "4"], "a": 3, "e": "Số trong ngoặc vuông là chu kỳ dao động; lõi 8051 cổ điển có 12 chu kỳ dao động mỗi chu kỳ máy, nên 48 / 12 = 4 chu kỳ máy."}, {"q": "unsigned char t = 200; t = t + 100; Sau đó t bằng bao nhiêu?", "o": ["300", "44", "255", "Không xác định, trình biên dịch báo lỗi"], "a": 1, "e": "300 = 12CH; unsigned char chỉ giữ 8 bit thấp 2CH = 44. Không có cảnh báo vì phép toán trên biến (không phải hằng)."}, {"q": "int a = -1; unsigned int b = 1; Biểu thức (a < b) có giá trị gì trong C?", "o": ["1 (đúng), vì −1 < 1", "Tùy trình biên dịch", "0 (sai), vì a được đổi sang unsigned thành 65535", "Lỗi dịch vì khác kiểu"], "a": 2, "e": "Quy tắc chuyển kiểu số học: int và unsigned int → cả hai thành unsigned int. −1 thành FFFFH = 65 535 > 1. SDCC không cảnh báo."}, {"q": "unsigned long ms = 60 * 1000; trên 8051 (int 16 bit) cho giá trị nào?", "o": ["60 000", "4 294 961 760 (FFFFEA60H)", "−5 536", "0"], "a": 1, "e": "60 * 1000 tính bằng int, tràn thành −5 536 (EA60H), rồi đổi sang unsigned long thành FFFFEA60H. SDCC báo warning 165 và 158. Viết 60UL * 1000."}, {"q": "Vì sao SDCC dịch x / 10 (x là unsigned char) thành lời gọi hàm thư viện chứ không dùng DIV AB?", "o": ["x được nâng lên int có dấu, còn DIV AB chỉ chia 8 bit không dấu", "8051 không có lệnh chia", "DIV AB chỉ chia cho 2", "Vì 10 không phải lũy thừa của 2 nên phải lặp"], "a": 0, "e": "Theo chuẩn C, toán hạng char được nâng lên int (có dấu, 16 bit); SDCC 4.2.0 gọi __divsint, __modsint (525 chu kỳ cho / và %). Hợp ngữ dùng DIV AB chỉ cần 4 chu kỳ."}]);

